"use client";

import React from "react";

interface FooterProps {
  tema: {
    yaziAna: string;
    yaziAlt: string;
    kenarlik: string;
  };
}

export default function Footer({ tema }: FooterProps) {
  return (
    <footer 
      className="mt-16 border-t pt-8 pb-12 text-center transition-colors"
      style={{ borderColor: tema.kenarlik }}
    >
      <div className="max-w-xl mx-auto space-y-2">
        <p className="font-bold text-base tracking-wide" style={{ color: tema.yaziAna }}>
          Çerkesçe Sözlük
        </p>
        <p className="text-sm font-normal" style={{ color: tema.yaziAlt }}>
          34 sözlük ve yüz binlerce kayıt içeren açık dijital Çerkesçe dil arşivi.
        </p>
        <p className="text-xs font-medium pt-2 opacity-75" style={{ color: tema.yaziAlt }}>
          Açık Mektep tarafından geliştirilmektedir.
        </p>
      </div>
    </footer>
  );
}